package run.ikaros.finance; import java.util.UUID; import org.springframework.http.MediaType; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/finance/ledgers/{ledgerId}/transactions/csv") public class FinanceCsvController{private final FinanceCsvService service;public FinanceCsvController(FinanceCsvService s){service=s;}@GetMapping(produces="text/csv")public Mono<String> export(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId){return service.export(a,ledgerId);}@PostMapping(consumes=MediaType.TEXT_PLAIN_VALUE)public Mono<CsvImportResult> importCsv(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId,@RequestBody String csv){return service.importCsv(a,ledgerId,csv);}}
